window.OdioNetwork=(()=>{
  const C=OdioNetworkCore,storageKey='eof-nodos-v1',thoughtKey='eof-pensamientos-v1';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let host,nodes=[],selectedId='w1',chosenTopics=[],chosenWords=[],view='explore',zoom=1,filter='Todos',pendingTopic='',draft='',positions=new Map(),inspectorHidden=false,pan=null;
  const localNodes=()=>{try{const raw=JSON.parse(localStorage.getItem(storageKey)||'[]');return Array.isArray(raw)?raw.slice(-60).filter(n=>n&&typeof n.text==='string'&&C.topics.includes(n.topic)&&typeof n.id==='string').map(n=>({...C.makeNode(n.text,n.topic,n.id),createdAt:n.createdAt})):[]}catch{return[]}};
  const savedThoughts=()=>{try{const data=JSON.parse(localStorage.getItem(thoughtKey)||"[]");return Array.isArray(data)?data.filter(t=>t&&typeof t.text==="string"&&Array.isArray(t.topics)&&Array.isArray(t.keywords)).slice(-30):[]}catch{return[]}};
  const selected=()=>nodes.find(n=>n.id===selectedId)||nodes[0];
  const records=()=>nodes.filter(n=>chosenTopics.includes(n.topic));
  const available=()=>C.wordCounts(records());
  function markup(){return `<div id="nodal-app" class="nodal-app"></div>`}
  function init(){host=document.querySelector('#nodal-app');nodes=[...C.seeds,...localNodes()];selectedId=nodes.filter(n=>n.local).at(-1)?.id||'w1';chosenTopics=[selected().topic];chosenWords=[];view='explore';zoom=1;filter='Todos';inspectorHidden=false;pan=null;host.addEventListener('click',onClick);host.addEventListener('submit',onSubmit);host.addEventListener('input',onInput);host.addEventListener('change',onChange);render()}
  function destroy(){if(host){host.removeEventListener('click',onClick);host.removeEventListener('submit',onSubmit);host.removeEventListener('input',onInput);host.removeEventListener('change',onChange)}host=null}
  function render(){if(!host)return;host.classList.toggle("is-exploring",view==="explore");host.innerHTML=`<header class="nodal-heading"><div><p class="eyebrow">COMUNIDAD DEL ODIO / REGISTROS QUE SE CRUZAN</p><h2 id="modal-title">LO QUE TE PASA<br><em>HACE RED.</em></h2></div><div class="nodal-header-actions"><button class="pill" data-net="create">+ CREAR MI NODO</button><button class="nodal-small" data-net="compose">CONSTRUIR UN PENSAMIENTO ↗</button><button class="nodal-small" data-net="saved">MIS PENSAMIENTOS (${savedThoughts().length})</button></div></header><div class="nodal-disclosure">PROTOTIPO LOCAL · ${C.seeds.length} REGISTROS DE EJEMPLO · ${nodes.filter(n=>n.local).length} NODOS TUYOS EN ESTE NAVEGADOR</div>${view==='create'?createView():view==='compose'?composeView():view==='saved'?savedView():exploreView()}`;if(view==='explore'){drawGraph();centerGraph();enableDrag();}if(view==='compose')updateThought();}
  function savedView(){const saved=savedThoughts().reverse();return `<div class="saved-thoughts"><p class="eyebrow" style="margin-top:35px">TUS PALABRAS QUEDAN ACÁ.</p>${saved.length?saved.map((r,i)=>`<article class="saved-thought"><h3>${esc(r.text)}</h3><p>${r.topics.map(esc).join(" / ")} · ${r.keywords.map(esc).join(" / ")}</p><button class="nodal-small" data-saved-thought="${i}">VOLVER A TRABAJAR ESTE PENSAMIENTO ↗</button></article>`).join(""):`<p class="thought-empty">Todavía no guardaste un pensamiento. Cruzá tópicos y palabras para construir el primero.</p>`}<button class="pill" data-net="compose" style="margin-top:30px">CONSTRUIR UN PENSAMIENTO ↗</button></div>`}
  function createView(){return `<div class="nodal-create"><div class="nodal-intro"><p class="eyebrow">01 / PONER AFUERA</p><h3>DECILO COMO<br>TE SALGA.</h3><p>Tu registro tiene un lugar en la red. El tópico lo acerca a otras voces; las palabras compartidas abren conexiones con otros temas.</p><button class="nodal-small" data-net="explore">← VOLVER A LA RED</button></div><form id="node-form"><label for="node-text">¿QUÉ TE MOLESTA? ¿QUÉ VENÍS AGUANTANDO?</label><textarea id="node-text" minlength="8" maxlength="500" required placeholder="Me desgasta trabajar todo el día y sentir que no tengo tiempo para mí…">${esc(draft)}</textarea><div class="form-info"><span>Sin nombre. Guardado solo en este navegador.</span><span id="node-count">${draft.length} / 500</span></div><label for="node-topic">¿DE QUÉ HABLA TU NODO?</label><select id="node-topic" required><option value="">Elegí un tópico</option>${C.topics.map(t=>`<option ${pendingTopic===t?'selected':''}>${t}</option>`).join('')}</select><p id="topic-hint" class="nodal-muted">Podés elegir el tema que mejor represente lo que escribiste.</p><p id="node-keywords" class="nodal-keyword-preview">${keywordPreview(draft)}</p><button class="pill" type="submit">CONSTRUIR MI NODO <span>↗</span></button><p id="node-error" role="status"></p></form></div>`}
  function keywordPreview(text){const words=C.keywords(text);return words.length?'PALABRAS QUE APARECEN: '+words.map(w=>w.toUpperCase()).join(' / '):'Tus palabras en común van a aparecer acá mientras escribís.'}
  function exploreView(){const node=selected(),related=C.related(node,nodes),visible=nodes.filter(n=>filter==='Todos'||n.topic===filter);return `<div class="nodal-toolbar"><label>EXPLORAR POR TÓPICO <select id="network-filter"><option>Todos</option>${C.topics.map(t=>`<option ${filter===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="nodal-legend"><span><i></i> REGISTRO</span><span><i class="your-dot"></i> TU NODO</span><span>— CONEXIÓN POR TEMA O PALABRA</span></div></div><div class="nodal-workspace"><div class="graph-column"><div class="graph-controls"><span>ARRASTRÁ PARA RECORRER · RUEDA PARA ZOOM · TOCÁ UN NODO PARA LEERLO</span><div><button data-net="toggle-list">REGISTROS</button><button data-net="zoom-out" aria-label="Alejar red">−</button><button data-net="zoom-reset">RESTAURAR</button><button data-net="zoom-in" aria-label="Acercar red">+</button></div></div><div class="graph-scroll" tabindex="0" aria-label="Red nodal, desplazable horizontalmente"><div class="graph-scene" style="width:${Math.max(innerWidth*1.7,1800)*zoom}px;height:${Math.max(innerHeight*1.6,1170)*zoom}px"><svg id="graph-lines" viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true"></svg><div id="graph-points"></div></div></div><details class="nodal-record-list"><summary>VER LOS ${visible.length} REGISTROS COMO LISTA</summary><div>${visible.map(n=>`<button data-node="${esc(n.id)}">${esc(n.topic)} / ${esc(n.text.slice(0,80))}${n.text.length>80?'…':''}</button>`).join('')}</div></details></div><aside class="node-inspector ${inspectorHidden?'is-hidden':''}"><button class="inspector-toggle" data-net="toggle-inspector" aria-label="Ocultar ficha del nodo">×</button><div class="inspector-top"><span>${node.local?'TU NODO / LOCAL':'REGISTRO DE EJEMPLO'}</span><span>${esc(node.topic.toUpperCase())}</span></div><h3>${esc(shortLabel(node))}</h3><blockquote>${esc(node.text)}</blockquote>${node.local?`<button class="nodal-small remove-node" data-net="remove-node">RETIRAR ESTE NODO LOCAL ×</button>`:""}<div class="node-tags">${node.keywords.map(w=>`<span>${esc(w)}</span>`).join('')||'<span>Conectado por tópico</span>'}</div><h4>${related.length} CONEXIONES CON SENTIDO</h4><div class="related-records">${related.slice(0,5).map(r=>`<button data-node="${esc(r.node.id)}"><span>${esc(r.node.topic)} ${r.node.local?'· TU NODO':''} ↗</span><strong>${esc(r.node.text.slice(0,92))}${r.node.text.length>92?'…':''}</strong><small>${esc(reason(r))}</small></button>`).join('')||'<p>Todavía no hay otro registro conectado. Podés cruzar este tema con otros desde el constructor.</p>'}</div><button class="pill" data-net="compose">CRUZAR ESTAS PALABRAS <span>↗</span></button></aside></div>`}
  function reason(r){return(r.sameTopic?'MISMO TÓPICO'+(r.words.length?' · ':''):'OTRO TÓPICO · ')+(r.words.length?'EN COMÚN: '+r.words.join(', '):'')}
  function shortLabel(n){if(n.local)return 'LO QUE VOS DESCARGASTE';const labels={w1:'EL TRABAJO ME CONSUME',w2:'RENDIR MÁS. COBRAR LO MISMO.',w3:'¿Y MI TIEMPO?',r1:'REPETIR HASTA EL DESGASTE',r2:'VIVIR EN AUTOMÁTICO',r3:'CALLAR TAMBIÉN CANSA',s1:'LA VIDA NO ALCANZA',s2:'COMPETIR O ENCONTRARNOS',a1:'LA PRESIÓN NO PARA',a2:'MIEDO EN SILENCIO',c1:'CUATRO HORAS MENOS',c2:'NO ME ESCUCHO',k1:'COMPRAR NO LO RESUELVE',k2:'SIEMPRE FALTA ALGO'};return labels[n.id]||n.topic}
  function drawGraph(){const hubs=[[290,210],[630,130],[780,400],[260,490],[100,340],[550,500]],visible=nodes.filter(n=>filter==='Todos'||n.topic===filter),svg=host.querySelector('#graph-lines'),points=host.querySelector('#graph-points');positions=new Map();for(let ti=0;ti<C.topics.length;ti++){const group=visible.filter(n=>n.topic===C.topics[ti]);const hub=hubs[ti];group.forEach((n,i)=>{const angle=(i*2.399+ti*.8),radius=70+Math.floor(i/5)*36;positions.set(n.id,{x:Math.max(28,Math.min(925,hub[0]+Math.cos(angle)*radius)),y:Math.max(60,Math.min(590,hub[1]+Math.sin(angle)*radius))})})}
    const relatedIds=new Set(C.related(selected(),nodes).map(r=>r.node.id));const edges=C.connections(visible);svg.innerHTML=edges.map(e=>{const a=positions.get(e.a),b=positions.get(e.b),focus=e.a===selectedId||e.b===selectedId;return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" class="${focus?'is-connected':''}"/>`}).join('');
    points.innerHTML=C.topics.filter(t=>visible.some(n=>n.topic===t)).map(t=>{const hub=hubs[C.topics.indexOf(t)];return `<span class="graph-topic" style="left:${hub[0]/10}%;top:${hub[1]/6.5}%">${esc(t.toUpperCase())}</span>`}).join('')+visible.map(n=>{const p=positions.get(n.id);return `<button class="graph-node ${n.id===selectedId?'is-selected':''} ${relatedIds.has(n.id)?'is-related':''} ${n.local?'is-yours':''}" data-node="${esc(n.id)}" style="left:${p.x/10}%;top:${p.y/6.5}%" aria-pressed="${n.id===selectedId}" aria-label="${esc(n.topic+': '+n.text)}"><i></i><span>${esc(n.local?'TU NODO':shortLabel(n))}</span></button>`}).join('');
  }
  function centerGraph(){const viewport=host.querySelector(".graph-scroll"),scene=host.querySelector(".graph-scene"),p=positions.get(selectedId);if(!viewport||!scene||!p)return;viewport.scrollLeft=Math.max(0,p.x/1000*scene.clientWidth-viewport.clientWidth*.42);viewport.scrollTop=Math.max(0,p.y/650*scene.clientHeight-viewport.clientHeight*.48);}
  function setGraphZoom(value,clientX,clientY){
    const viewport=host?.querySelector('.graph-scroll'),scene=host?.querySelector('.graph-scene');
    if(!viewport||!scene)return;
    const next=Math.max(.65,Math.min(1.8,value));
    if(next===zoom)return;
    const rect=viewport.getBoundingClientRect();
    const x=clientX===undefined?viewport.clientWidth/2:clientX-rect.left-viewport.clientLeft;
    const y=clientY===undefined?viewport.clientHeight/2:clientY-rect.top-viewport.clientTop;
    const anchorX=(viewport.scrollLeft+x)/scene.clientWidth;
    const anchorY=(viewport.scrollTop+y)/scene.clientHeight;
    zoom=next;
    scene.style.width=`${Math.max(innerWidth*1.7,1800)*zoom}px`;
    scene.style.height=`${Math.max(innerHeight*1.6,1170)*zoom}px`;
    viewport.scrollLeft=anchorX*scene.clientWidth-x;
    viewport.scrollTop=anchorY*scene.clientHeight-y;
    pan=null;
    viewport.classList.remove('is-dragging');
  }
  function onGraphWheel(e){
    if(!e.deltaY)return;
    e.preventDefault();
    const viewport=e.currentTarget;
    const unit=e.deltaMode===1?16:e.deltaMode===2?viewport.clientHeight:1;
    const delta=Math.max(-240,Math.min(240,e.deltaY*unit));
    setGraphZoom(zoom*Math.exp(-delta*.0015),e.clientX,e.clientY);
  }
  function enableDrag(){const viewport=host.querySelector(".graph-scroll");viewport.addEventListener('wheel',onGraphWheel,{passive:false});viewport.onpointerdown=e=>{if(e.button!==0||e.target.closest("button"))return;pan={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture(e.pointerId);viewport.classList.add("is-dragging");};viewport.onpointermove=e=>{if(!pan)return;viewport.scrollLeft=pan.left-(e.clientX-pan.x);viewport.scrollTop=pan.top-(e.clientY-pan.y);};const end=()=>{pan=null;viewport.classList.remove("is-dragging")};viewport.onpointerup=end;viewport.onpointercancel=end;viewport.onlostpointercapture=end;}
  function composeView(){const pool=records(),counts=available(),thought=C.thought(chosenTopics,chosenWords,records());return `<div class="thought-layout"><div class="thought-builder"><p class="eyebrow">02 / DEL REGISTRO AL PENSAMIENTO</p><h3>LO QUE NOS UNE<br>NO ES CASUALIDAD.</h3><p>Elegí los temas que querés cruzar. Las palabras disponibles salen de esos registros; cada una muestra cuántas voces la comparten.</p><fieldset><legend>1. CONECTÁ DISTINTOS TÓPICOS</legend><div class="topic-choices">${C.topics.map(t=>`<button data-topic="${t}" aria-pressed="${chosenTopics.includes(t)}">${t} <small>${nodes.filter(n=>n.topic===t).length}</small></button>`).join('')}</div></fieldset><fieldset><legend>2. ELEGÍ HASTA 3 PALABRAS CLAVE</legend><div class="word-choices">${counts.map(({word,count,topics})=>`<button data-word="${word}" aria-pressed="${chosenWords.includes(word)}">${word} <small>${count} ${count===1?'voz':'voces'} · ${topics.length} ${topics.length===1?'tópico':'tópicos'}</small></button>`).join('')||'<p>Elegí al menos un tópico.</p>'}</div></fieldset><p id="word-limit" role="status"></p><div class="thought-actions"><button class="nodal-small" data-net="explore">← VOLVER A LA RED</button><button class="nodal-small" data-net="auto-words">SUGERIR PALABRAS ↗</button></div><details class="thought-sources"><summary>VER LOS ${pool.length} REGISTROS DE ESTOS TÓPICOS</summary>${pool.map(n=>`<article><small>${esc(n.topic)} · ${n.local?'TU NODO':'EJEMPLO'}</small><p>${esc(n.text)}</p></article>`).join('')}</details></div><div class="thought-output"><span class="thought-kicker">03 / UNA VOZ QUE PODEMOS COMPARTIR</span><div class="thought-preview" id="thought-preview" aria-live="polite">${esc(thought)||'CONECTÁ TEMAS.<br>ELEGÍ PALABRAS.<br>ENCONTRÁ TU VOZ.'}</div><label for="thought-edit">TU PENSAMIENTO · PODÉS REESCRIBIRLO</label><textarea id="thought-edit" maxlength="240" placeholder="La frase aparece al elegir palabras…">${esc(thought)}</textarea><p class="nodal-muted">Propuesta automática por palabras en común. Vos decidís cómo decirlo.</p><div id="thought-evidence"></div><button class="pill" data-net="save-thought" ${thought?'':'disabled'}>GUARDAR ESTE PENSAMIENTO <span>↓</span></button><p id="thought-status" role="status"></p><div class="stencil-next"><span>DESPUÉS / LLEVARLO A LA CALLE</span><p>Este pensamiento y sus palabras quedan listos para una próxima sesión de plantilla gráfica o stencil.</p></div></div></div>`}
  function updateThought(){const field=host.querySelector('#thought-edit');if(!field)return;const evidence=records().filter(n=>n.keywords.some(w=>chosenWords.includes(w)));host.querySelector('#thought-evidence').innerHTML=chosenWords.length?`<details><summary>¿DE DÓNDE SALE? ${evidence.length} REGISTROS CON ESTAS PALABRAS</summary>${evidence.map(n=>`<article><small>${esc(n.topic)} · ${n.local?'TU NODO':'EJEMPLO'}</small><p>${esc(n.text)}</p><div>${n.keywords.filter(w=>chosenWords.includes(w)).map(w=>`<span>${esc(w)}</span>`).join('')}</div></article>`).join('')}</details>`:''}
  function onClick(e){const target=e.target.closest('button');if(!target)return;if(target.dataset.savedThought!==undefined){const record=savedThoughts().reverse()[Number(target.dataset.savedThought)];if(!record)return;chosenTopics=record.topics.filter(t=>C.topics.includes(t));chosenWords=record.keywords.filter(w=>available().some(v=>v.word===w));view="compose";render();host.querySelector("#thought-edit").value=record.text;host.querySelector("#thought-preview").textContent=record.text;host.querySelector("[data-net=save-thought]").disabled=!record.text.trim();return}if(target.dataset.node){selectedId=target.dataset.node;inspectorHidden=false;filter="Todos";chosenTopics=[selected().topic];chosenWords=selected().keywords.slice(0,3);view='explore';render();return}if(target.dataset.topic){const t=target.dataset.topic;chosenTopics=chosenTopics.includes(t)?chosenTopics.filter(v=>v!==t):[...chosenTopics,t];const possible=new Set(available().map(w=>w.word));chosenWords=chosenWords.filter(w=>possible.has(w));render();return}if(target.dataset.word){const w=target.dataset.word;if(chosenWords.includes(w))chosenWords=chosenWords.filter(v=>v!==w);else if(chosenWords.length<3)chosenWords.push(w);else{host.querySelector('#word-limit').textContent='Elegí hasta tres palabras para que el pensamiento tenga un foco.';return}render();return}switch(target.dataset.net){case'toggle-list':{const list=host.querySelector('.nodal-record-list');list.open=!list.open;break;}case'toggle-inspector':inspectorHidden=!inspectorHidden;host.querySelector('.node-inspector')?.classList.toggle('is-hidden',inspectorHidden);break;case'remove-node':{const node=selected();if(!node.local)return;const rest=nodes.filter(n=>n.local&&n.id!==node.id);try{localStorage.setItem(storageKey,JSON.stringify(rest));nodes=[...C.seeds,...rest];selectedId='w1';chosenTopics=['Trabajo'];chosenWords=[];render()}catch{target.textContent='NO SE PUDO RETIRAR. REVISÁ EL ALMACENAMIENTO.'}break;}case'saved':view='saved';render();break;case'create':view='create';draft='';pendingTopic='';render();host.querySelector('#node-text').focus();break;case'explore':view='explore';render();break;case'compose':view='compose';if(!chosenTopics.length)chosenTopics=[selected().topic];if(!chosenWords.length)chosenWords=available().slice(0,2).map(v=>v.word);render();break;case'auto-words':chosenWords=available().slice(0,3).map(v=>v.word);render();break;case'zoom-in':setGraphZoom(zoom+.2);break;case'zoom-out':setGraphZoom(zoom-.2);break;case'zoom-reset':zoom=1;render();break;case'save-thought':saveThought();break}}
  function onInput(e){if(e.target.id==='node-text'){draft=e.target.value;host.querySelector('#node-count').textContent=draft.length+' / 500';host.querySelector('#node-keywords').textContent=keywordPreview(draft);const suggested=C.suggestTopic(draft);host.querySelector('#topic-hint').textContent=suggested?'POR TUS PALABRAS, PODRÍA SER: '+suggested.toUpperCase()+'. Podés cambiarlo.':'Elegí el tema que mejor represente lo que escribiste.';if(!pendingTopic&&suggested)host.querySelector('#node-topic').value=suggested}if(e.target.id==='thought-edit'){host.querySelector('#thought-preview').textContent=e.target.value||'ENCONTRÁ TU VOZ.';host.querySelector('[data-net="save-thought"]').disabled=!e.target.value.trim()}}
  function onChange(e){if(e.target.id==='node-topic')pendingTopic=e.target.value;if(e.target.id==='network-filter'){filter=e.target.value;const found=nodes.find(n=>filter==='Todos'||n.topic===filter);if(found&&filter!=='Todos')selectedId=found.id;render()}}
  function onSubmit(e){if(e.target.id!=='node-form')return;e.preventDefault();try{const node=C.makeNode(draft,host.querySelector('#node-topic').value,'local-'+(crypto.randomUUID?.()||Date.now()));const previous=nodes.filter(n=>n.local);localStorage.setItem(storageKey,JSON.stringify([...previous,node].slice(-60)));nodes=[...C.seeds,...[...previous,node].slice(-60)];selectedId=node.id;chosenTopics=[node.topic];chosenWords=node.keywords.slice(0,3);view='explore';filter='Todos';draft='';render();}catch(error){host.querySelector('#node-error').textContent=error.message||'No se pudo guardar el nodo. Revisá el almacenamiento del navegador.'}}
  function saveThought(){const text=host.querySelector('#thought-edit').value.trim();if(!text)return;const sourceIds=records().filter(n=>n.keywords.some(w=>chosenWords.includes(w))).map(n=>n.id);const record={id:'thought-'+Date.now(),text,topics:[...chosenTopics],keywords:[...chosenWords],sourceIds,createdAt:new Date().toISOString()};try{let old;try{old=JSON.parse(localStorage.getItem(thoughtKey)||'[]')}catch{old=[]}localStorage.setItem(thoughtKey,JSON.stringify([...(Array.isArray(old)?old:[]),record].slice(-30)));const content=`EL ODIO EN FRANCÉS / PENSAMIENTO\n\n${text}\n\nTópicos: ${chosenTopics.join(', ')}\nPalabras: ${chosenWords.join(', ')}\nRegistros de origen: ${sourceIds.join(', ')}\n\nPrototipo local: combina registros de ejemplo y nodos de este navegador.\nPróxima instancia: plantilla gráfica / stencil.\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='el-odio-mi-pensamiento.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);host.querySelector('[data-net=saved]').textContent='MIS PENSAMIENTOS ('+savedThoughts().length+')';host.querySelector('#thought-status').textContent='Guardado en este navegador y descargado con sus tópicos, palabras y registros de origen.'}catch{host.querySelector('#thought-status').textContent='No se pudo guardar. El texto sigue acá para que puedas copiarlo.'}}
  return{markup,init,destroy};
})();
